// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }

    function testFuzz_property(uint256 initialMint, uint256 burnAmount) public {
        initialMint = bound(initialMint, 0, type(uint256).max / 2);
        burnAmount = bound(burnAmount, 0, type(uint256).max / 2);

        if (initialMint > 0) {
            c.mintToken(address(this), initialMint);
        }

        uint256 beforeSupply = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(address(this));

        vm.assume(burnAmount <= beforeBalance);

        bool ok;
        try c.burn(burnAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.totalSupply() + burnAmount == beforeSupply);
        } else {
            assertTrue(c.totalSupply() == beforeSupply);
        }
    }
}
